src = './challenge/dds1-alpine.flag.img.gz'
flag_pattern = b'picoCTF{'

with gzip.open(src, 'rb') as f:
    # Read in chunks and search for the flag
    chunk_size = 1024*1024  # 1MB
    prev_tail = b''
    while True:
        chunk = f.read(chunk_size)
        if not chunk:
            break
        data = prev_tail + chunk
        idx = data.find(flag_pattern)
        if idx != -1:
            # Found the flag, extract it
            end = data.find(b'}', idx)
            if end != -1:
                flag = data[idx:end+1].decode('utf-8', errors='replace')
                print(f"Found flag: {flag}")
                break
        prev_tail = data[-100:]  # Keep last 100 bytes for overlap
    else:
        print("Flag not found in first pass")"}

